using System.Data;
using FlowPro.Application.Common;
using Microsoft.EntityFrameworkCore;

namespace FlowPro.Infrastructure.Persistence;

/// <summary>
/// Transaction wrapper for workspace provisioning.
/// </summary>
/// <remarks>
/// Identical to <see cref="EfUnitOfWork" /> except that the row level security scope comes from the
/// caller instead of the authenticated identity. This is required because provisioning writes the
/// tenant it is creating, so no tenant exists in the request identity yet. The tenant identifier is
/// generated by the caller before the transaction opens and applied here.
/// </remarks>
internal sealed class EfProvisioningUnitOfWork(FlowProDbContext dbContext) : IProvisioningUnitOfWork
{
    public async Task<TResult> ExecuteInTenantScopeAsync<TResult>(
        Guid tenantId,
        Func<CancellationToken, Task<TResult>> operation,
        CancellationToken cancellationToken)
    {
        if (tenantId == Guid.Empty)
        {
            throw new ArgumentException("A tenant scope is required.", nameof(tenantId));
        }

        Microsoft.EntityFrameworkCore.Storage.IExecutionStrategy executionStrategy =
            dbContext.Database.CreateExecutionStrategy();

        return await executionStrategy.ExecuteAsync(
            async () =>
            {
                dbContext.ChangeTracker.Clear();
                await using Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction transaction =
                    await dbContext.Database.BeginTransactionAsync(
                        IsolationLevel.ReadCommitted,
                        cancellationToken);

                await dbContext.Database.ExecuteSqlInterpolatedAsync(
                    $"SELECT set_config('flowpro.tenant_id', {tenantId.ToString()}, true)",
                    cancellationToken);

                TResult result = await operation(cancellationToken);
                await dbContext.SaveChangesAsync(cancellationToken);
                await transaction.CommitAsync(cancellationToken);
                return result;
            });
    }
}
